    singles=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j] not in (0,2)]
    for i,j,c in singles: out[i][j]=0
    def nb(p,q): return abs(p[0]-q[0])<=1 and abs(p[1]-q[1])<=1 and p!=q
    res=[]
    for i,j,c in singles:
        # nearest block
        best=min(blk,key=lambda B:min(nb((i,j),br) for br in B[:2]))  # block key = top-left
        tb,tb0,tb1=best[0]
        # use top-left
        bl=[(tb,tb0),(tb,tb1),(tb0,tb0),(tb0,tb1)]
        b=min(bl,key=lambda b_:max(abs(i-b_[0]),abs(j-b_[1])))
        cy,cx=b[0]+0.5,b[1]+0.5
        ur,uc=i-cy,j-cx
        ru,ru2=uc,-ur  # CW rotation
        tr,tc=int(math.floor(cy+ru2)),int(math.floor(cx+ru))
        res.append((tr,tc,c))
        # extension: tangent = CW of normalized u
        dr=(1 if ur>=0 else -1 if ur<0 else 0)
